-- Data simulasi awal: 63 kejadian (dari lib/incidents.ts versi sebelumnya), waktu relatif terhadap saat migrasi dijalankan.
-- Sebelum demo, segarkan waktunya: select public.refresh_demo_incidents();
begin;



-- Laporan yang digabung harus merujuk kejadian yang ada.
alter table public.reports
  add constraint reports_incident_id_fkey foreign key (incident_id) references public.incidents (id) on delete set null;

-- Laporan yang sudah terbit sebelum tabel kejadian ada ikut diterbitkan ke peta.
select public.publish_report(id) from public.reports where status = 'terbit' order by created_at;

commit;
